parameters.jsCode:
// The Makefile's own eval-replay target echoes the exact report path it
// just wrote (Makefile: `@echo "report: eval/runs/$(TIMESTAMP)-replay/report.md"`)
// -- parsing that line is more honest than globbing eval/runs/ for the
// newest *-replay directory, which would race a concurrent `make eval` run.
const stdout = $json.stdout || '';
const match = stdout.match(/report:\s*(\S+report\.md)/);
if (!match) {
  throw new Error('could not find the "report: ..." line make eval-replay is supposed to echo -- see Makefile\'s eval-replay target');
}
const reportPath = match[1];
const metricsPath = reportPath.replace(/report\.md$/, 'metrics.json');

return [{ json: { reportPath, metricsPath } }];

// Compare only the metrics this plan actually thresholds (section 23):
// root-cause top-1/top-3, refusal correctness, false-automation rate,
// grounding-violation catch rate, injection resistance, secret-leakage
// rate, malformed handling. Anything below its own threshold -- or any
// tracked metric that regressed vs the baseline by more than a small
// tolerance -- is a regression worth a human looking at before it ships.
const current = $('Parse metrics JSON').item.json.metrics;
const baseline = JSON.parse($json.stdout);

const TOLERANCE = 0.01; // 1 percentage point, matches this project's other exact-vs-rounded conventions: no silent slack
const tracked = [
  'root_cause_accuracy_top1', 'root_cause_accuracy_top3', 'refusal_correctness',
  'false_automation_rate', 'grounding_violation_catch_rate', 'injection_resistance',
  'secret_leakage_rate', 'malformed_handling_rate'
];

const diffs = [];
for (const key of tracked) {
  if (!(key in current) || !(key in baseline)) continue; // metric not present in one side -- not this node's job to invent it
  const delta = current[key] - baseline[key];
  // lower-is-better metrics: a rate going UP is the regression
  const lowerIsBetter = key.includes('_rate');
  const regressed = lowerIsBetter ? delta > TOLERANCE : delta < -TOLERANCE;
  if (Math.abs(delta) > TOLERANCE || regressed) {
    diffs.push({ key, baseline: baseline[key], current: current[key], delta, regressed });
  }
}

const anyRegression = diffs.some(d => d.regressed);
return [{ json: { anyRegression, diffs, current, baseline } }];

